function evidence = f90_xaero11_extract_reference_evidence(modelPath, outputRoot, officialScenarios, evaluatorAssetRoot)
%F90_XAERO11_EXTRACT_REFERENCE_EVIDENCE Public native ADCS replay.
arguments
    modelPath (1,1) string
    outputRoot (1,1) string
    officialScenarios
    evaluatorAssetRoot (1,1) string
end

modelPath = string(modelPath);
outputRoot = string(outputRoot);
sourceRoot = string(evaluatorAssetRoot);
runtimeRoot = string(getenv("SIMUVERITY_RUNTIME_SUBMISSION_BUNDLE"));
assert(isfolder(sourceRoot), "SimuVerity:XAERO11:MissingAssetRoot", ...
    "Evaluator-owned XAERO-11 reference assets are absent: %s", sourceRoot);
assert(isfolder(runtimeRoot), "SimuVerity:XAERO11:MissingRuntimeRoot", ...
    "Fresh XAERO-11 runtime bundle is absent: %s", runtimeRoot);

model = "BFN_00_zfull_system";
relativeModel = fullfile("src_simulink", model + ".slx");
assetModel = fullfile(sourceRoot, relativeModel);
runtimeModel = fullfile(runtimeRoot, relativeModel);
expectedModelPresence = ...
    "present";
assert(isfile(modelPath) && localSamePath(modelPath, runtimeModel) && ...
    localFilePresence(modelPath) == expectedModelPresence, ...
    "SimuVerity:XAERO11:ReferenceRuntimeIdentity", ...
    "The selected reference is not the exact runtime source entrypoint.");
localAssertAsset(assetModel, expectedModelPresence, "AssetModelIdentity");
localAssertAsset(runtimeModel, expectedModelPresence, "RuntimeModelIdentity");

% Bind every direct initializer input in both the immutable evaluator asset
% closure and the fresh writable runtime copy.  The retained public reference
% inventory binds the remaining transitive files.
boundFiles = {
    "LICENSE", ...
        "present"; ...
    "README.md", ...
        "present"; ...
    fullfile("src_matlab", "BFN_00_main.m"), ...
        "present"; ...
    fullfile("funs", "spher2car.m"), ...
        "present"; ...
    fullfile("funs", "sh2020.mat"), ...
        "present"; ...
    relativeModel, expectedModelPresence};
for index = 1:size(boundFiles, 1)
    relativePath = string(boundFiles{index, 1});
    expectedPresence = string(boundFiles{index, 2});
    localAssertAsset(fullfile(sourceRoot, relativePath), expectedPresence, ...
        "AssetClosureIdentity");
    localAssertAsset(fullfile(runtimeRoot, relativePath), expectedPresence, ...
        "RuntimeClosureIdentity");
end

contract = localOfficialScenarios(officialScenarios);
cases = contract.scenarios;
if iscell(cases), cases = [cases{:}]; end
scoringRunId = strtrim(string(getenv("SIMUVERITY_SCORING_RUN_ID")));
assert(strlength(scoringRunId) > 0, "SimuVerity:XAERO11:ScoringRunIdRequired", ...
    "Reference extraction requires a fresh SimuVerity ScoringRunId.");
if isfolder(outputRoot) || isfile(outputRoot)
    error("SimuVerity:XAERO11:OutputExists", ...
        "Fresh output root already exists: %s", outputRoot);
end
mkdir(outputRoot);
mkdir(fullfile(outputRoot, "scenario_data"));

oldFolder = string(pwd);
oldPath = path;
sessionCleanup = onCleanup(@() localRestoreSession( ...
    oldFolder, oldPath, model)); %#ok<NASGU>
scratchRoot = string(tempname);
assert(~isfolder(scratchRoot) && ~isfile(scratchRoot), ...
    "SimuVerity:XAERO11:ScratchExists", ...
    "Fresh evaluator scratch path already exists: %s", scratchRoot);
mkdir(scratchRoot);
scratchCleanup = onCleanup(@() localRemoveTree(scratchRoot)); %#ok<NASGU>
cacheRoot = fullfile(scratchRoot, "cache");
codegenRoot = fullfile(scratchRoot, "codegen");
mkdir(cacheRoot);
mkdir(codegenRoot);
Simulink.fileGenControl("set", "CacheFolder", cacheRoot, ...
    "CodeGenFolder", codegenRoot, "createDir", true);

identityNames = {"LICENSE", "README.md", "src_matlab/BFN_00_main.m", ...
    "src_simulink/BFN_00_zfull_system.slx", "funs/sh2020.mat"};
e = struct( ...
    "schema", "simuverity.f90-xaero11-fixed-evidence.v1", ...
    "task_id", "F90-XAERO-11", ...
    "scoring_run_id", char(scoringRunId), ...
    "current_phase", "reference", ...
    "matlab_release", version("-release"), ...
    "source_identity", ...
        "Meisam-Tavakoli-97-spacecraft-adcs-f1675f2348a8be8aa9e45b49de37fbbec3710ce4", ...
    "source_tree_file_presence", ...
        "present", ...
    "source_file_count", 53, ...
    "core_source_modifications", 0, ...
    "runtime_parameter_and_logging_overrides_only", true, ...
    "reference_source_modified_or_saved", false, ...
    "reference_model_file_presence", expectedModelPresence, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "simulate_pass", false, ...
    "all_scenarios_valid", false, ...
    "evidence_complete", false, ...
    "error_identifier", "", ...
    "error_message", "");
e.source_file_presence = localBindingFiles(sourceRoot, identityNames);
e.runtime_file_presence = localBindingFiles(runtimeRoot, identityNames);
e.scenarios = struct([]);
e.structure = struct( ...
    "orbit_and_ephemeris_propagation", true, ...
    "quaternion_rigid_body_dynamics", true, ...
    "environmental_disturbance_torques", true, ...
    "noisy_sensors_and_filtering", true, ...
    "dynamic_attitude_determination", true, ...
    "detumbling_and_eigenaxis_slew_modes", true, ...
    "magnetorquer_and_thruster_allocation", true, ...
    "closed_feedback_paths", true);
e.mode_switch_mapping = struct( ...
    "operation_mode_0", "Manual Switch sw=1: Detumbler", ...
    "operation_mode_1", "Manual Switch sw=0: Slew eigenaxis");

wallTimer = tic;
try
    restoredefaultpath;
    cd(runtimeRoot);
    addpath(fullfile(runtimeRoot, "src_matlab"), "-begin");
    evalin("base", "BFN_00_main");
    localAssertOfficialWorkspace;

    timer = tic;
    load_system(runtimeModel);
    e.load_s = toc(timer);
    e.load_pass = bdIsLoaded(model) && ...
        localSamePath(string(get_param(model, "FileName")), runtimeModel);
    assert(e.load_pass, "SimuVerity:XAERO11:LoadedModelIdentity", ...
        "MATLAB did not load the exact runtime reference entrypoint.");
    set_param(model, "LimitDataPoints", "off");
    workspaceSinks = find_system(model, "BlockType", "ToWorkspace");
    for sinkIndex = 1:numel(workspaceSinks)
        set_param(workspaceSinks{sinkIndex}, "MaxDataPoints", "inf");
    end
    disturbancePorts = get_param(model + "/Disturbances/Sum1", "PortHandles");
    set_param(disturbancePorts.Outport, "DataLogging", "on", ...
        "DataLoggingNameMode", "Custom", ...
        "DataLoggingName", "disturbance_torque_tap");
    set_param(model, "SignalLogging", "on", "SignalLoggingName", "logsout");
    e.evaluator_owned_signal_taps = { ...
        "Disturbances/Sum1 output as disturbance_torque_tap"};

    timer = tic;
    set_param(model, "SimulationCommand", "update");
    e.update_s = toc(timer);
    e.update_pass = true;
    timer = tic;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    e.compile_s = toc(timer);
    e.compile_pass = true;

    for caseIndex = 1:numel(cases)
        result = localRunCase(model, outputRoot, cases(caseIndex), caseIndex);
        if isempty(e.scenarios)
            e.scenarios = result;
        else
            e.scenarios(end + 1) = result; %#ok<AGROW>
        end
    end
    e.simulation_seconds = sum([e.scenarios.simulate_s]);
    e.simulate_pass = all([e.scenarios.valid]);
    e.all_scenarios_valid = e.simulate_pass && ...
        numel(e.scenarios) == 6;
catch exception
    e.error_identifier = exception.identifier;
    e.error_message = getReport(exception, "extended", "hyperlinks", "off");
    try, feval(model, [], [], [], "term"); catch, end
end

e.total_wall_clock_s = toc(wallTimer);
e.source_file_presence_after = localBindingFiles(sourceRoot, identityNames);
e.runtime_file_presence_after = localBindingFiles(runtimeRoot, identityNames);
e.runtime_model_unchanged = isequal(e.runtime_file_presence, e.runtime_file_presence_after);
e.load_update_compile_simulate = e.load_pass && e.update_pass && ...
    e.compile_pass && e.simulate_pass && e.all_scenarios_valid && ...
    e.runtime_model_unchanged;
e.evidence_complete = e.load_update_compile_simulate;
localWriteJson(fullfile(outputRoot, "evidence.json"), e);
evidence = e;
end

function contract = localOfficialScenarios(value)
if isstruct(value)
    contract = value;
else
    scenarioPath = string(value);
    assert(isfile(scenarioPath), "SimuVerity:XAERO11:OfficialScenariosMissing", ...
        "Official scenarios are absent: %s", scenarioPath);
    contract = jsondecode(fileread(scenarioPath));
end
assert(isfield(contract, "schema") && ...
    string(contract.schema) == "simuverity.official-scenarios.v1" && ...
    isfield(contract, "task_id") && ...
    string(contract.task_id) == "F90-XAERO-11" && ...
    isfield(contract, "scenarios"), ...
    "SimuVerity:XAERO11:OfficialScenarioContract", ...
    "The public official scenario contract is invalid.");
rows = contract.scenarios;
if iscell(rows), rows = [rows{:}]; end
assert(numel(rows) == 6, "SimuVerity:XAERO11:OfficialScenarioCount", ...
    "XAERO-11 requires exactly six official scenarios.");
required = ["id", "operation_mode", "initial_body_rate_rad_s", ...
    "target_inertial_unit_vector", "sensor_noise_scale", ...
    "disturbance_scale"];
assert(all(isfield(rows, required)), "SimuVerity:XAERO11:OfficialScenarioFields", ...
    "An official scenario is missing a required public input.");

expectedIds = ["nominal_slew", "three_axis_detumble", ...
    "skew_rate_recovery", "high_sensor_noise", "high_disturbance", ...
    "combined_stress"];
expectedModes = [1, 0, 0, 1, 1, 1];
expectedRates = { ...
    [0; 0; 0], [0.035; -0.025; 0.045], [-0.05; 0.04; -0.03], ...
    [0; 0; 0], [0; 0; 0], [0.02; -0.015; 0.03]};
expectedTargets = { ...
    [1; 0; 0], [1; 0; 0], [1; 0; 0], [0; 1; 0], [0; 0; 1], ...
    [0.5773502691896258; 0.5773502691896258; 0.5773502691896258]};
expectedNoise = [1, 1, 1, 5, 1, 3];
expectedDisturbance = [1, 1, 1, 1, 2, 1.8];
for index = 1:numel(rows)
    row = rows(index);
    assert(string(row.id) == expectedIds(index) && ...
        double(row.operation_mode) == expectedModes(index) && ...
        isequal(double(row.initial_body_rate_rad_s(:)), expectedRates{index}) && ...
        isequal(double(row.target_inertial_unit_vector(:)), ...
            expectedTargets{index}) && ...
        double(row.sensor_noise_scale) == expectedNoise(index) && ...
        double(row.disturbance_scale) == expectedDisturbance(index), ...
        "SimuVerity:XAERO11:OfficialScenarioIdentity", ...
        "Official XAERO-11 scenario %d is missing or changed.", index);
end
contract.scenarios = rows;
end

function scenario = localRunCase(model, outputRoot, config, index)
simulationInput = Simulink.SimulationInput(model);
simulationInput = simulationInput.setVariable("today_mjd2000", 9000.0);
simulationInput = simulationInput.setVariable( ...
    "w0", double(config.initial_body_rate_rad_s(:)));
simulationInput = simulationInput.setVariable( ...
    "targets_inertial", repmat( ...
        double(config.target_inertial_unit_vector(:)), 1, 3));
noiseScale = double(config.sensor_noise_scale);
disturbanceScale = double(config.disturbance_scale);
simulationInput = simulationInput.setVariable( ...
    "Magn_noise", 1.18e-9 * sqrt(0.5) * noiseScale);
simulationInput = simulationInput.setVariable( ...
    "IFEHS_noise", 0.0101e-2 * sqrt(0.5) * noiseScale);
simulationInput = simulationInput.setVariable( ...
    "Gyro_noise_n", 0.01 / 60 * pi / 180 * sqrt(1e3) * noiseScale);
simulationInput = simulationInput.setVariable( ...
    "Gyro_noise_b", 1 / 3600 * pi / 180 * sqrt(1e3) * noiseScale);
simulationInput = simulationInput.setVariable( ...
    "m_disturb", [0.01; 0.05; 0.01] * 0.5e-2 * disturbanceScale);
simulationInput = simulationInput.setVariable( ...
    "Cd", 2.2 * disturbanceScale);
if double(config.operation_mode) == 0
    switchValue = "1";
else
    switchValue = "0";
end
simulationInput = simulationInput.setBlockParameter( ...
    model + "/Manual Switch", "sw", switchValue);
simulationInput = simulationInput.setModelParameter( ...
    "StopTime", "100", "TimeOut", 120, ...
    "ReturnWorkspaceOutputs", "on", "SimulationMode", "normal");

rng(314159 + index, "twister");
timer = tic;
simulationOutput = sim(simulationInput);
simulationSeconds = toc(timer);
[time, q] = localNativeSeries(simulationOutput, "q");
[omegaTime, omega] = localNativeSeries(simulationOutput, "omega");
omega = localAlignTo(time, omegaTime, omega);
[qeTime, qe] = localNativeSeries(simulationOutput, "qe");
qe = localAlignTo(time, qeTime, qe);
[attitudeErrorTime, attitudeError] = localNativeSeries( ...
    simulationOutput, "att_det_err");
attitudeError = localAlignTo(time, attitudeErrorTime, attitudeError);
[angleErrorTime, angleError] = localNativeSeries(simulationOutput, "ang_e");
angleError = localAlignTo(time, angleErrorTime, angleError);
[magnetorquerTime, magnetorquerTorque] = localNativeSeries( ...
    simulationOutput, "control_magn");
magnetorquerTorque = localAlignTo( ...
    time, magnetorquerTime, magnetorquerTorque);
[thrusterTime, thrusterTorque] = localNativeSeries( ...
    simulationOutput, "control_thr");
thrusterTorque = localAlignTo(time, thrusterTime, thrusterTorque);
[dipoleTime, dipole] = localNativeSeries(simulationOutput, "m");
dipole = localAlignTo(time, dipoleTime, dipole);

logged = simulationOutput.get("logsout");
tap = logged.getElement("disturbance_torque_tap");
tapTime = double(tap.Values.Time(:));
disturbanceTorque = double(tap.Values.Data);
if size(disturbanceTorque, 1) ~= numel(tapTime) && ...
        size(disturbanceTorque, ndims(disturbanceTorque)) == numel(tapTime)
    disturbanceTorque = permute(disturbanceTorque, ...
        [ndims(disturbanceTorque), 1:(ndims(disturbanceTorque) - 1)]);
end
disturbanceTorque = reshape( ...
    disturbanceTorque, size(disturbanceTorque, 1), []);
assert(size(disturbanceTorque, 1) == numel(tapTime), ...
    "SimuVerity:XAERO11:TapAlignment", ...
    "The evaluator-owned disturbance tap is not time aligned.");
disturbanceTorque = localAlignTo(time, tapTime, disturbanceTorque);

assert(size(q, 2) >= 4 && size(omega, 2) >= 3 && size(qe, 2) >= 4, ...
    "SimuVerity:XAERO11:StateWidth", ...
    "Native attitude output width is incomplete.");
assert(size(magnetorquerTorque, 2) >= 3 && ...
    size(thrusterTorque, 2) >= 3 && size(dipole, 2) >= 3 && ...
    size(disturbanceTorque, 2) >= 3, ...
    "SimuVerity:XAERO11:ActuatorWidth", ...
    "Native actuator or disturbance output width is incomplete.");
qsf = [q(:,4), q(:,1:3)];
qesf = [qe(:,4), qe(:,1:3)];
attitude = [qsf, omega(:,1:3)];
estimation = [qesf, attitudeError(:,1)];
actuator = [magnetorquerTorque(:,1:3), thrusterTorque(:,1:3)];
environment = [dipole(:,1:3), disturbanceTorque(:,1:3)];
data = struct( ...
    "time_s", time, ...
    "attitude_state", attitude, ...
    "estimation_state", estimation, ...
    "actuator_state", actuator, ...
    "environment_state", environment, ...
    "attitude_error_native", angleError);
identifier = string(config.id);
dataFile = fullfile(outputRoot, "scenario_data", identifier + ".mat");
save(dataFile, "data", "-v7.3");
canonicalBinding = localCanonicalDataBinding(data, outputRoot);

tail = time >= 80;
trueNorm = sqrt(sum(qsf .^ 2, 2));
estimatedNorm = sqrt(sum(qesf .^ 2, 2));
rateNorm = sqrt(sum(omega(:,1:3) .^ 2, 2));
controlNorm = sqrt(sum(actuator .^ 2, 2));
disturbanceNorm = sqrt(sum(disturbanceTorque(:,1:3) .^ 2, 2));
metrics = struct( ...
    "true_quaternion_norm_max_error", max(abs(trueNorm - 1)), ...
    "estimated_quaternion_norm_max_error", max(abs(estimatedNorm - 1)), ...
    "initial_body_rate_norm_rad_s", rateNorm(1), ...
    "tail_body_rate_rms_rad_s", sqrt(mean(rateNorm(tail) .^ 2)), ...
    "peak_body_rate_rad_s", max(rateNorm), ...
    "tail_attitude_error_rms", ...
        sqrt(mean(sum(angleError(tail,:) .^ 2, 2))), ...
    "attitude_estimation_error_rms", ...
        sqrt(mean(attitudeError(:,1) .^ 2)), ...
    "control_torque_rms_Nm", sqrt(mean(controlNorm .^ 2)), ...
    "control_torque_peak_Nm", max(controlNorm), ...
    "magnetorquer_torque_peak_Nm", ...
        max(sqrt(sum(magnetorquerTorque(:,1:3) .^ 2, 2))), ...
    "thruster_torque_peak_Nm", ...
        max(sqrt(sum(thrusterTorque(:,1:3) .^ 2, 2))), ...
    "magnetic_dipole_peak_Am2", ...
        max(sqrt(sum(dipole(:,1:3) .^ 2, 2))), ...
    "disturbance_torque_rms_Nm", sqrt(mean(disturbanceNorm .^ 2)), ...
    "attitude_dynamic_range", max(max(attitude(:,1:4), [], 1) - ...
        min(attitude(:,1:4), [], 1)), ...
    "actuator_dynamic_range_Nm", max(max(actuator, [], 1) - ...
        min(actuator, [], 1)), ...
    "all_finite", all(isfinite([time; attitude(:); estimation(:); ...
        actuator(:); environment(:); angleError(:)])));
logs = struct( ...
    "attitude_state", localLogInfo(attitude, ...
        {"1", "1", "1", "1", "rad/s", "rad/s", "rad/s"}), ...
    "estimation_state", localLogInfo(estimation, ...
        {"1", "1", "1", "1", "rad"}), ...
    "actuator_state", localLogInfo(actuator, ...
        {"N*m", "N*m", "N*m", "N*m", "N*m", "N*m"}), ...
    "environment_state", localLogInfo(environment, ...
        {"A*m^2", "A*m^2", "A*m^2", "N*m", "N*m", "N*m"}));
valid = metrics.all_finite && numel(time) >= 50 && abs(time(1)) < 1e-9 && ...
    time(end) >= 99.9 && all(diff(time) > 0) && ...
    size(attitude, 2) == 7 && size(estimation, 2) == 5 && ...
    size(actuator, 2) == 6 && size(environment, 2) == 6;
scenario = struct( ...
    "id", char(identifier), ...
    "inputs", rmfield(config, "id"), ...
    "simulate_s", simulationSeconds, ...
    "data_file", char("scenario_data/" + identifier + ".mat"), ...
    "data_file_file_presence", localFilePresence(dataFile), ...
    "canonical_data_file_presence", canonicalBinding, ...
    "logs", logs, ...
    "metrics", metrics, ...
    "valid", valid);
end

function output = localLogInfo(value, units)
output = struct( ...
    "channels", size(value, 2), ...
    "samples", size(value, 1), ...
    "units", {units});
end

function [time, value] = localNativeSeries(simulationOutput, name)
value = simulationOutput.get(name);
rawTime = simulationOutput.get("time");
if isa(value, "timeseries")
    time = double(value.Time(:));
    value = double(value.Data);
elseif isa(value, "Simulink.SimulationData.Signal")
    time = double(value.Values.Time(:));
    value = double(value.Values.Data);
else
    value = double(value);
    if isa(rawTime, "timeseries")
        time = double(rawTime.Data(:));
    else
        time = double(rawTime(:));
    end
end
if size(value, 1) ~= numel(time)
    if size(value, ndims(value)) == numel(time)
        value = permute(value, [ndims(value), 1:(ndims(value) - 1)]);
    elseif size(value, 2) == numel(time)
        value = value.';
    end
end
value = reshape(value, size(value, 1), []);
assert(size(value, 1) == numel(time), "SimuVerity:XAERO11:OutputAlignment", ...
    "Native output %s does not align with its actual logged time base.", name);
assert(all(isfinite(time)) && all(isfinite(value), "all"), ...
    "SimuVerity:XAERO11:Nonfinite", ...
    "Native output %s contains nonfinite samples.", name);
end

function value = localAlignTo(targetTime, sourceTime, sourceValue)
if isequal(targetTime, sourceTime)
    value = sourceValue;
    return
end
[uniqueTime, index] = unique(sourceTime, "stable");
sourceValue = sourceValue(index, :);
value = interp1(uniqueTime, sourceValue, targetTime, "previous", "extrap");
end

function binding = localCanonicalDataBinding(data, outputRoot)
canonicalPath = string(tempname(outputRoot)) + ".bin";
deleteCleanup = onCleanup(@() localDeleteFile(canonicalPath)); %#ok<NASGU>
fid = fopen(canonicalPath, "w", "ieee-le");
assert(fid >= 0, "SimuVerity:XAERO11:CanonicalWrite", ...
    "Cannot create canonical evidence stream.");
fileCleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fields = ["time_s", "attitude_state", "estimation_state", ...
    "actuator_state", "environment_state", "attitude_error_native"];
for index = 1:numel(fields)
    localWriteArray(fid, data.(fields(index)));
end
clear fileCleanup
binding = localFilePresence(canonicalPath);
clear deleteCleanup
end

function localWriteArray(fid, value)
shape = uint64(size(value));
fwrite(fid, uint64(numel(shape)), "uint64");
fwrite(fid, shape, "uint64");
fwrite(fid, double(value(:)), "double");
end

function result = localBindingFiles(root, names)
result = struct;
for index = 1:numel(names)
    relativePath = string(names{index});
    field = matlab.lang.makeValidName(char(relativePath));
    result.(field) = localFilePresence(fullfile(root, relativePath));
end
end

function localAssertOfficialWorkspace()
required = ["today_mjd2000", "w0", "targets_inertial", "Magn_noise", ...
    "IFEHS_noise", "Gyro_noise_n", "Gyro_noise_b", "m_disturb", ...
    "Cd", "agh", "dgh", "Jsc"];
for index = 1:numel(required)
    assert(evalin("base", "exist('" + required(index) + "','var') == 1"), ...
        "SimuVerity:XAERO11:OfficialInitializationIncomplete", ...
        "The official initializer did not define %s.", required(index));
end
end

function localAssertAsset(pathValue, expectedPresence, token)
assert(isfile(pathValue) && localFilePresence(pathValue) == lower(expectedPresence), ...
    "SimuVerity:XAERO11:" + token, ...
    "A source-bound XAERO-11 asset is missing or changed: %s", pathValue);
end

function binding = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
binding = "present";
end

function localWriteJson(pathValue, value)
fid = fopen(pathValue, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:XAERO11:EvidenceWrite", ...
    "Cannot write public reference evidence: %s", pathValue);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fprintf(fid, "%s\n", jsonencode(value, PrettyPrint=true));
end

function localRestoreSession(oldFolder, oldPath, model)
try
    if bdIsLoaded(model), close_system(model, 0); end
catch
end
try, cd(oldFolder); catch, end
try, path(oldPath); catch, end
end

function same = localSamePath(firstPath, secondPath)
first = char(java.io.File(char(firstPath)).getCanonicalPath());
second = char(java.io.File(char(secondPath)).getCanonicalPath());
if ispc
    same = strcmpi(first, second);
else
    same = strcmp(first, second);
end
end

function localDeleteFile(pathValue)
if isfile(pathValue), delete(pathValue); end
end

function localRemoveTree(pathValue)
if isfolder(pathValue), rmdir(pathValue, "s"); end
end
